import React, {useState} from "react";

type CardOnline = {
    id: number,
    title: string,
    isDone: boolean,
}

export const LectureTwoUS1 = () => {
    const[criteria, setCriteria] = useState<CardOnline[]>(
        [
            {id:1, title:'Минимальная длина создаваемого пароля составляет четыре символа.', isDone:true},
            {id:2, title:'Разрешить использование любых символов при создании пароля.', isDone:true},
            {id:3, title:'Срок действия пароля – один год.', isDone:true},
            {id:4, title:'Отправляется SMS-оповещение с только что созданным паролем клиенту банка.', isDone:true},
            {id:5, title:'Блокировка карты после трёх последовательных неудачных попыток ввода пароля.', isDone:true},
        ]
    )

    return (
        <div style={{display: 'flex', flexDirection: 'column', padding: 30}}>
            <h3 style={{display: 'flex', alignItems: 'center', flexDirection: 'column'}}>
                User story №1 Карта онлайн</h3>
            <p style={{display: 'flex', alignItems: 'center', flexDirection: 'column'}}>
                Я как клиент банка,
                хочу иметь возможность самостоятельно создать пароль для цифровой карты,
                чтобы не запоминать сгенерированный</p>
            <ul>
                {criteria.map((cri: CardOnline) => {

                    return (
                        <li key={cri.id} style={{display: 'flex', alignItems: 'center', flexDirection: 'row'}}>
                            <input type='checkbox' checked={cri.isDone}
                            />
                            <span>{cri.title}</span>
                        </li>
                    )
                })
                }
            </ul>
        </div>
    )
}