import React, {FC, useState} from "react";
import {PATH} from "../../Pages";
import {NavLink} from "react-router-dom";

type OnlineStoreType = {
    id: number,
    title: string,
    isDone: boolean,
}

type PropsType = {
    open?: boolean;
    handleClose?: () => void;
};

export const OnlineStore: FC<PropsType> = ({ open, handleClose }) => {
    const[competences, setCompetences] = useState<OnlineStoreType[]>(
        [
            {id:1, title:'Сайт необходимо запустить через пару месяцев', isDone:true},
            {id:2, title:'Стек технологий: PNPM, VITE, REACT', isDone:true},
            {id:3, title:'Монолитная архитектура', isDone:true},
            {id:4, title:'Афиша сайта будет доступна для всех посетителей', isDone:true},
            {id:5, title:'Для желающих участвовать необходимо пройти регистрацию', isDone:true},
            {id:6, title:'После регистрации пользователь попадает в личный кабинет', isDone:true},
            {id:7, title:'На сайте будет реализован календарь с афишей', isDone:true},
            {id:8, title:'Зарегистрированный пользователь сможет бронировать место для участия', isDone:true},
            {id:9, title:'Пользователи смогут отменять бронь', isDone:true},
            {id:10, title:'Под афишей мероприятия участники смогут оставлять комментарии', isDone:true},
            {id:11, title:'Пользователи ' +
                    'смогут оставлять пожелания о будущих мероприятиях', isDone:true},
        ]
    )

    return (
        <div style={{display: 'flex', flexDirection: 'column', padding: 30}}>
            {open && <div onClick={handleClose}/>}
            <aside>
                <h3 style={{display: 'flex', alignItems: 'center', flexDirection: 'column'}}>Лекция №1 ДЗ №2 Интернет-магазин</h3>
                <p style={{display: 'flex', alignItems: 'center', flexDirection: 'column'}}>Какая из методологий больше подходит для реализации программного
                    обеспечения (нового Интернет-магазина), обоснуйте свой выбор.
                    Предварительно опишите предполагаемый ИМ </p>
                <h3>Описание ИМ спортивные мероприятия для любителей</h3>
                <ul>
                    {competences.map((competence: OnlineStoreType) => {

                        return (
                            <li key={competence.id}>
                                <input type='checkbox' checked={competence.isDone}
                                />
                                <span>{competence.title}</span>
                            </li>
                        )
                    })
                    }
                </ul>
                <h3>Для реализации ПО данного ИМ больше подходит Scrum</h3>
                <nav>
                    <ul>
                        <li>
                            <span>{'1. Небольшой сайт с монолитной архитектурой подходит для маленькой команды '}</span>
                            <NavLink
                                to={PATH.ScrumKanban}
                            >
                                 Лекция №1 ДЗ Scrum и Kanban
                            </NavLink>
                        </li>
                        <li>
                            <span>{'2. После первого спринта (1-4 недели) появиться MVP '}</span>
                            <NavLink
                                to={PATH.ScrumKanban}
                            >
                                 Лекция №1 ДЗ Scrum и Kanban
                            </NavLink>
                        </li>
                        <li>
                    <span>{'3. Scrum создавался, чтобы быстро разработать\n' +
                        '                  продукт '}</span>
                            <NavLink
                                to={PATH.ScrumKanban}
                            >
                                Лекция №1 ДЗ Scrum и Kanban
                            </NavLink>
                        </li>
                    </ul>
                </nav>
            </aside>
        </div>
    )
}