import React, {FC} from "react";
import {NavLink} from "react-router-dom";
import {PATH} from "../../Pages";

type PropsType = {
    open?: boolean;
    handleClose?: () => void;
};

export const LectureFour: FC<PropsType> = ({ open, handleClose }) => {
    return (
        <div>
            {open && <div onClick={handleClose} />}

            <aside >

                <nav style={{display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
                    <NavLink
                        to={PATH.LectureFourUC}
                        onClick={handleClose}
                        className={({ isActive }) => (isActive ? 'active1' : 'nav1')}
                    >
                        Лекция №4 ДЗ Use case
                    </NavLink>
                    <NavLink
                        to={PATH.LectureFourSequence}
                        onClick={handleClose}
                        className={({ isActive }) => (isActive ? 'active1' : 'nav1')}
                    >
                        Лекция №4 ДЗ Sequence
                    </NavLink>
                    <NavLink
                        to={PATH.LectureFourActivity}
                        onClick={handleClose}
                        className={({ isActive }) => (isActive ? 'active1' : 'nav1')}
                    >
                        Лекция №4 ДЗ Activity
                    </NavLink>
                </nav>
            </aside>
        </div>
    )
}
