import React, {useState} from "react";

type CardOnline = {
    id: number,
    title: string,
    isDone: boolean,
}

export const LectureTwoUS2 = () => {
    const[criteria, setCriteria] = useState<CardOnline[]>(
        [
            {id:1, title:'Разрешить клиенту дозаказать от 1 до 5 пластиковых карт к цифровой карте.', isDone:true},
            {id:2, title:'Клиент вправе отозвать заявку на получение пластиковой карты.', isDone:true},
            {id:3, title:' Клиент может самостоятельно определить место получения пластиковой карты.', isDone:true},
            {id:4, title:'Разрешить клиенту возможность блокировки пластиковой карты онлайн.', isDone:true},
            {id:5, title:'Клиент может устанавливать лимит на снятие денежных средств для пластиковой карты.', isDone:true},
        ]
    )

    return (
        <div style={{display: 'flex', flexDirection: 'column', padding: 30}}>
            <h3 style={{display: 'flex', alignItems: 'center', flexDirection: 'column'}}>
                User story №2 Карта онлайн</h3>
            <p style={{display: 'flex', alignItems: 'center', flexDirection: 'column'}}>
                Я как клиент банка, хочу иметь возможность дозаказать пластиковую карту к цифровой,
                чтобы проводить оплату на устройствах, не поддерживающих NFC.</p>
            <ul>
                {criteria.map((cri: CardOnline) => {

                    return (
                        <li key={cri.id} style={{display: 'flex', alignItems: 'center', flexDirection: 'row'}}>
                            <input type='checkbox' checked={cri.isDone}
                            />
                            <h5>{cri.title}</h5>
                        </li>
                    )
                })
                }
            </ul>
        </div>
    )
}