import React, {FC} from "react";
import {NavLink} from "react-router-dom";
import {PATH} from "../../Pages";

type PropsType = {
    open?: boolean;
    handleClose?: () => void;
};

export const LectureFiveMain: FC<PropsType> = ({ open, handleClose }) => {
    return (
        <div style={{display: 'flex', flexDirection: 'column', padding: 30}}>
            {open && <div onClick={handleClose}/>}

            <aside>
                <h3 style={{display: 'flex', alignItems: 'center', flexDirection: 'column'}}>
                    Лекция №5 ДЗ Диаграмма классов</h3>
                <nav>
                    Постройте<br/>
                    <NavLink
                        to={PATH.LectureFiveClass}
                    >
                        ОДНУ диаграмму классов
                    </NavLink>
                    <br/>
                    Обязательно использование на диаграмме таких видов отношений, как ассоциация, наследование,
                    агрегация (минимум 1), композиция (минимум 1);<br/>
                    Количество методов от 1-4;<br/>
                    К атрибутам необходимо добавить Видимость, Наименование и Тип;<br/>
                    Количество классов не меньше 5.<br/>
                    Постройте<br/>
                    <NavLink
                        to={PATH.LectureFiveState}
                    >
                        диаграмму состояний
                    </NavLink>
                    <br/>
                    Требования:
                    Инструменты без ограничений. Предпочтительные инструменты: Draw.io или PlantUml.
                    Результат представить в одном из форматов: pdf, word
                    Обязательно должно быть приложено описание
                    <NavLink
                        to={PATH.LectureTwoUC}
                    >
                        UC
                    </NavLink>

                    на основе которой были реализованы диаграммы. Иначе ДЗ проверено не будет

                </nav>
            </aside>
        </div>
    )
}