import {PATH} from "../../Pages";
import React, {FC} from "react";
import {NavLink} from "react-router-dom";


type PropsType = {
    open?: boolean;
    handleClose?: () => void;
};

export const MainBoard: FC<PropsType> = ({ open, handleClose }) => {
    return (
        <div>
            {open && <div onClick={handleClose} />}

            <aside >

                <nav style={{display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
                    <NavLink
                        to={PATH.ScrumKanban}
                        onClick={handleClose}
                        className={({ isActive }) => (isActive ? 'active1' : 'nav1')}
                    >
                        Лекция №1 ДЗ Scrum и Kanban
                    </NavLink>
                    <NavLink
                        to={PATH.OnlineStore}
                        onClick={handleClose}
                        className={({ isActive }) => (isActive ? 'active1' : 'nav1')}
                    >
                        Лекция №1 ДЗ Интернет-магазин
                    </NavLink>
                    <NavLink
                        to={PATH.KanbanBoard}
                        onClick={handleClose}
                        className={({ isActive }) => (isActive ? 'active1' : 'nav1')}
                    >
                        Лекция №1 ДЗ Канбан доска
                    </NavLink>
                </nav>
            </aside>
        </div>
    )
}