import MainPhoto from '../../assets/images/activity.svg'
import React from "react";
import {NavLink} from "react-router-dom";
import {PATH} from "../../Pages";

export const  LectureFourActivity = () => {
    return (
        <div style={{display: 'flex', flexDirection: 'column', padding: 30}}>
            <h3 style={{display: 'flex', alignItems: 'center', flexDirection: 'column'}}>Лекция №4 ДЗ Activity</h3>
            <p>Подготовить Activity
                <NavLink
                    to={PATH.LectureTwoUC}
                >
                    для Use Case (из ДЗ №2)
                </NavLink>
                Требования:
                Инструменты без ограничений. Предпочтительные инструменты: Draw.io или PlantUml.
                Результат представить в одном из форматов: jpg, png, svg, pdf</p>
            <img style={{
                alignSelf: 'center',
                width: 240,
                height: 200, objectFit: 'cover'
            }} src={MainPhoto}/>
        </div>
    )
}