import React, {FC} from 'react'
import {useLocation} from 'react-router-dom'
import {PATH} from '../Pages'

type PropsType = {
    handleOpen: () => void
}

export const Header: FC<PropsType> = ({handleOpen}) => {
    const location = useLocation()
    const currentPath = location.pathname

    const pageName =
        currentPath === PATH.MainBoard ? 'Лекция №1' :
            currentPath === PATH.LectureTwo ? 'Лекция №2' :
                currentPath === PATH.LectureThree ? 'Лекция №3' :
                    currentPath === PATH.LectureFour ? 'Лекция №4' :
                        currentPath === PATH.LectureFive ? 'Лекция №5' :
                            currentPath === PATH.LectureSix ? 'Лекция №6' :
                                currentPath === PATH.LectureSeven ? 'Лекции №7-8' : ''
    return (
        <>
            <div>
                <h1>{pageName}</h1>
            </div>
        </>
    )
}