import React, {FC} from "react";
import {NavLink} from "react-router-dom";
import {PATH} from "../../Pages";

type PropsType = {
    open?: boolean;
    handleClose?: () => void;
};

export const LectureSix: FC<PropsType> = ({ open, handleClose }) => {
    return (
        <div>
            {open && <div onClick={handleClose} />}

            <aside >

                <nav style={{display: 'flex', alignItems: 'center', flexDirection: 'column'}}>
                    <NavLink
                        to={PATH.LectureSixMain}
                        onClick={handleClose}
                        className={({ isActive }) => (isActive ? 'active1' : 'nav1')}
                    >
                        Лекция №6 ДЗ Архитектура
                    </NavLink>
                </nav>
            </aside>
        </div>
    )
}